(function() {
  window.CardSpoke.Plugin.register('minimal-writer', {
    manifest: {
      name: 'Minimal Writer',
      version: '1.0.0',
      author: 'CardSpoke Community',
      description: 'Rebrands as a minimalist writing app with clean typography and simplified interface',
      layer: 'app',
      permissions: ['ui-override', 'storage']
    },
    setup: async function(ctx) {
      document.body.classList.add('minimal-writer-active');
      var badge = document.createElement('div');
      badge.className = 'minimal-writer-badge';
      var wordCount = 0;
      var cardCount = 0;
      var updateBadge = function() {
        try {
          var cards = ctx.api.data.listCards();
          cardCount = cards.length;
          wordCount = cards.reduce(function(sum, c) {
            var text = (c.title || '') + ' ' + (c.body || '');
            return sum + text.trim().split(/\s+/).filter(function(w) { return w.length > 0; }).length;
          }, 0);
          badge.textContent = cardCount + ' notes · ' + wordCount.toLocaleString() + ' words';
        } catch (err) {
          badge.textContent = 'Minimal Writer';
        }
      };
      updateBadge();
      document.body.appendChild(badge);
      this._badge = badge;
      this._updateBadge = updateBadge;
      var headerTitle = document.querySelector('.header h1, header h1');
      if (headerTitle) {
        headerTitle.textContent = 'Writer';
      }
      if (window.CardSpoke && window.CardSpoke.Middleware) {
        window.CardSpoke.Middleware.register({
          name: 'minimal-writer-update',
          priority: -100,
          operations: ['card.save', 'card.delete'],
          handler: async function(mwCtx, next) {
            await next();
            setTimeout(function() {
              if (updateBadge) updateBadge();
            }, 100);
          }
        });
      }
      ctx.logger.info('Minimal Writer loaded');
    },
    teardown: async function(ctx) {
      if (window.CardSpoke && window.CardSpoke.Middleware) {
        window.CardSpoke.Middleware.unregister('minimal-writer-update');
      }
      document.body.classList.remove('minimal-writer-active');
      if (this._badge && this._badge.parentNode) {
        this._badge.remove();
      }
      var headerTitle = document.querySelector('.header h1, header h1');
      if (headerTitle && headerTitle.textContent === 'Writer') {
        headerTitle.textContent = 'CardSpoke';
      }
      ctx.logger.info('Minimal Writer disabled');
    }
  });
})();
